// Writes src/flavor.generated.ts: which app this is (Moonbook or Moonbook Test)
// and its version, from the same settings app.config.js reads.
import fs from "node:fs";
const tester = process.env.MB_TESTER === "1";
const run = Number(process.env.GITHUB_RUN_NUMBER || 0);
const version = run ? `0.2.${run}` : "0.1.0";
fs.writeFileSync(new URL("../src/flavor.generated.ts", import.meta.url),
  "// Generated by scripts/flavor.mjs. Don't edit.\n" +
  `export const TESTER = ${tester};\nexport const VERSION = ${JSON.stringify(version)};\n`);
console.log("flavor:", tester ? "Moonbook Test" : "Moonbook", version);
